apolloQueryPlan.text:
QueryPlan {
  Sequence {
    Fetch(service: "clubs") {
      {
        club(id: "c1") {
          name
          owner {
            __typename
            id
          }
          currentBook {
            __typename
            id
          }
        }
      }
    },
    Parallel {
      Sequence {
        Flatten(path: "club.currentBook") {
          Fetch(service: "catalog") {
            {
              ... on Book {
                __typename
                id
              }
            } =>
            {
              ... on Book {
                pages
                title
              }
            }
          },
        },
        Flatten(path: "club.currentBook") {
          Fetch(service: "clubs") {
            {
              ... on Book {
                __typename
                pages
                id
              }
            } =>
            {
              ... on Book {
                weeksToRead
              }
            }
          },
        },
      },
      Sequence {
        Flatten(path: "club.currentBook") {
          Fetch(service: "reviews") {
            {
              ... on Book {
                __typename
                id
              }
            } =>
            {
              ... on Book {
                averageRating
                reviews {
                  rating
                  author {
                    __typename
                    id
                    handle
                  }
                }
              }
            }
          },
        },
        Flatten(path: "club.currentBook.reviews.@.author") {
          Fetch(service: "accounts") {
            {
              ... on User {
                __typename
                id
              }
            } =>
            {
              ... on User {
                name
              }
            }
          },
        },
      },
      Flatten(path: "club.owner") {
        Fetch(service: "accounts") {
          {
            ... on User {
              __typename
              id
            }
          } =>
          {
            ... on User {
              name
            }
          }
        },
      },
    },
  },
}
